mkdir -p /tmp/i18ncheck && cat > /tmp/i18ncheck/check.test.tsx <<'EOF'
import { test, expect } from 'vitest';
import * as React from 'react';
import { renderToString } from 'react-dom/server';
import { ThemeProvider } from '@gravity-ui/uikit';
import { appI18n } from '/home/sandbox/workspace/src/i18n/keyset';

function Probe({ count }: { count: number }) {
  const { t } = appI18n.useTranslation();
  return <span>{t('title')}|{t('label_items', { count })}|{t('greeting', { name: 'Ann' })}</span>;
}
const render = (lang: string, count: number) =>
  renderToString(<ThemeProvider theme="light" lang={lang}><Probe count={count} /></ThemeProvider>);

test('app keysets', () => {
  console.log(render('en', 1), render('en', 5));
  console.log([1, 3, 5, 21, 1.5].map((c) => render('ru', c)).join('\n'));
});

test('full app in ru', async () => {
  (globalThis as any).window = { localStorage: { getItem: () => null, setItem() {} }, navigator: { language: 'ru-RU' } };
  const { App } = await import('/home/sandbox/workspace/src/App');
  const { LangProvider } = await import('/home/sandbox/workspace/src/i18n/LangProvider');
  const html = renderToString(<LangProvider><App /></LangProvider>);
  expect(html).toContain('Добро пожаловать');
  expect(html).toContain('Следующая'); // Pagination's own keyset
  console.log(html.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' '));
});
EOF
npx vitest run --root / /tmp/i18ncheck/check.test.tsx 2>&1 | grep -v "^$" | head -40

sed -e "s#/home/sandbox/workspace/src#../src#g" /tmp/i18ncheck/check.test.tsx > ./tmp-i18n-check.test.tsx && cat > tmp-vitest.config.ts <<'EOF'
